<?php
namespace App\Services;
use App\Models\{LoyaltyAccount,LoyaltyTransaction,Order,User,Wallet,WalletTransaction};
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
class LoyaltyWalletService {
 public const POINTS_PER_PHP=1; public const REDEMPTION_POINTS=100; public const REDEMPTION_PHP=1;
 public function wallet(User $user): Wallet { return $user->wallet()->firstOrCreate([],['balance'=>0,'currency'=>'PHP']); }
 public function loyalty(User $user): LoyaltyAccount { return $user->loyaltyAccount()->firstOrCreate([],['points'=>0,'tier'=>'bronze']); }
 public function debit(User $user,float $amount,string $description='Wallet payment',?Order $order=null): WalletTransaction { if($amount<=0) throw ValidationException::withMessages(['amount'=>'Debit amount must be greater than zero.']); return DB::transaction(function()use($user,$amount,$description,$order){$w=Wallet::where('user_id',$user->id)->lockForUpdate()->first();if(!$w || (float)$w->balance+0.0001<$amount) throw ValidationException::withMessages(['payment'=>'Insufficient wallet balance.']);$w->balance=(float)$w->balance-$amount;$w->save();return WalletTransaction::create(['wallet_id'=>$w->id,'type'=>'debit','amount'=>-$amount,'balance_after'=>$w->balance,'reference'=>'FH-WPAY-'.Str::upper(Str::random(12)),'description'=>$description,'order_id'=>$order?->id]);}); }
 public function credit(User $user,float $amount,string $type='adjustment',?string $description=null,?Order $order=null,?User $actor=null): WalletTransaction { if($amount<=0) throw ValidationException::withMessages(['amount'=>'Credit amount must be greater than zero.']); return DB::transaction(function()use($user,$amount,$type,$description,$order,$actor){$w=Wallet::where('user_id',$user->id)->lockForUpdate()->first()??Wallet::create(['user_id'=>$user->id,'balance'=>0,'currency'=>'PHP']);$w->balance=(float)$w->balance+$amount;$w->save();return WalletTransaction::create(['wallet_id'=>$w->id,'type'=>$type,'amount'=>$amount,'balance_after'=>$w->balance,'reference'=>'FH-WAL-'.Str::upper(Str::random(12)),'description'=>$description,'order_id'=>$order?->id,'created_by'=>$actor?->id]);}); }
 public function redeem(User $user,int $points): array { if($points<self::REDEMPTION_POINTS || $points%self::REDEMPTION_POINTS!==0) throw ValidationException::withMessages(['points'=>'Points must be redeemed in blocks of 100.']); return DB::transaction(function()use($user,$points){$a=LoyaltyAccount::where('user_id',$user->id)->lockForUpdate()->first()??LoyaltyAccount::create(['user_id'=>$user->id,'points'=>0,'tier'=>'bronze']); if($a->points<$points) throw ValidationException::withMessages(['points'=>'Insufficient loyalty points.']);$wallet=Wallet::where('user_id',$user->id)->lockForUpdate()->first()??Wallet::create(['user_id'=>$user->id,'balance'=>0,'currency'=>'PHP']);$cash=$points/self::REDEMPTION_POINTS*self::REDEMPTION_PHP;$a->points-=$points;$a->tier=$this->tier($a->points);$a->save();$ref='FH-LOY-'.Str::upper(Str::random(12));LoyaltyTransaction::create(['loyalty_account_id'=>$a->id,'type'=>'redeem','points'=>-$points,'balance_after'=>$a->points,'reference'=>$ref,'description'=>'Points redeemed to wallet']);$wallet->balance=(float)$wallet->balance+$cash;$wallet->save();WalletTransaction::create(['wallet_id'=>$wallet->id,'type'=>'reward','amount'=>$cash,'balance_after'=>$wallet->balance,'reference'=>$ref,'description'=>'Loyalty points redemption']);return ['points'=>$a->points,'tier'=>$a->tier,'wallet_balance'=>(float)$wallet->balance,'credited'=>(float)$cash];}); }
 public function rewardForOrder(Order $order): ?LoyaltyTransaction { return DB::transaction(function()use($order){$a=LoyaltyAccount::where('user_id',$order->customer_id)->lockForUpdate()->first()??LoyaltyAccount::create(['user_id'=>$order->customer_id,'points'=>0,'tier'=>'bronze']); if(LoyaltyTransaction::where('order_id',$order->id)->where('type','earn')->exists()) return null;$points=(int)floor((float)$order->grand_total*self::POINTS_PER_PHP); if($points<=0)return null;$a->points+=$points;$a->tier=$this->tier($a->points);$a->save();return LoyaltyTransaction::create(['loyalty_account_id'=>$a->id,'type'=>'earn','points'=>$points,'balance_after'=>$a->points,'reference'=>'FH-ORD-'.str_pad((string)$order->id,10,'0',STR_PAD_LEFT), 'description'=>'Reward for completed order','order_id'=>$order->id]);}); }
 public function adjust(User $user,int $points,?User $actor=null,string $description='Loyalty adjustment'): LoyaltyTransaction { if($points===0) throw ValidationException::withMessages(['points'=>'Points cannot be zero.']); return DB::transaction(function()use($user,$points,$actor,$description){$a=LoyaltyAccount::where('user_id',$user->id)->lockForUpdate()->first()??LoyaltyAccount::create(['user_id'=>$user->id,'points'=>0,'tier'=>'bronze']);$next=$a->points+$points;if($next<0) throw ValidationException::withMessages(['points'=>'Adjustment would make the balance negative.']);$a->points=$next;$a->tier=$this->tier($a->points);$a->save();return LoyaltyTransaction::create(['loyalty_account_id'=>$a->id,'type'=>'adjustment','points'=>$points,'balance_after'=>$a->points,'reference'=>'FH-ADJ-'.Str::upper(Str::random(12)),'description'=>$description,'created_by'=>$actor?->id]);}); }
 private function tier(int $points): string { return $points>=5000?'platinum':($points>=2000?'gold':($points>=500?'silver':'bronze')); }
}
